188	  /**
189	   * Enforces rate limiting for a request. Should be converted to a servlet filter at some point.
190	   * Currently, this is tightly coupled with request tracing which is not ideal either.
191	   *
192	   * @param request The request to limit
193	   * @param response The associated response
194	   * @param limitedExecution code that will be traced
195	   */
196	  static void rateLimitRequest(
197	      RateLimitManager rateLimitManager,
198	      HttpServletRequest request,
199	      HttpServletResponse response,
200	      Runnable limitedExecution)
201	      throws ServletException, IOException {
202	    boolean accepted = false;
203	    try {
204	      accepted = rateLimitManager.handleRequest(request);
205	      if (!accepted) {
206	        response.sendError(ErrorCode.TOO_MANY_REQUESTS.code, RateLimitManager.ERROR_MESSAGE);
207	        return;
208	      }
209	      // todo: this shouldn't be required, tracing and rate limiting should be independently
210	      // composable
211	      traceHttpRequestExecution2(request, response, limitedExecution);
212	    } catch (InterruptedException e) {
213	      Thread.currentThread().interrupt();
214	      throw new SolrException(ErrorCode.SERVER_ERROR, e.getMessage());
215	    } finally {
216	      if (accepted) {
217	        rateLimitManager.decrementActiveRequests(request);
218	      }
219	    }
220	  }
