47	public class TestRequestRateLimiter extends SolrCloudTestCase {
48	  private static final String FIRST_COLLECTION = "c1";
49	  private static final String SECOND_COLLECTION = "c2";
50	
51	  @BeforeClass
52	  public static void setupCluster() throws Exception {
53	    configureCluster(1).addConfig(FIRST_COLLECTION, configset("cloud-minimal")).configure();
54	  }
55	
56	  @Test
57	  public void testConcurrentQueries() throws Exception {
58	    try (CloudSolrClient client =
59	        cluster.basicSolrClientBuilder().withDefaultCollection(FIRST_COLLECTION).build()) {
60	
61	      CollectionAdminRequest.createCollection(FIRST_COLLECTION, 1, 1).process(client);
62	      cluster.waitForActiveCollection(FIRST_COLLECTION, 1, 1);
63	
64	      SolrDispatchFilter solrDispatchFilter = cluster.getJettySolrRunner(0).getSolrDispatchFilter();
65	
66	      RateLimiterConfig rateLimiterConfig =
67	          new RateLimiterConfig(
68	              SolrRequest.SolrRequestType.QUERY,
69	              true,
70	              1,
71	              DEFAULT_SLOT_ACQUISITION_TIMEOUT_MS,
72	              5 /* allowedRequests */,
73	              true /* isSlotBorrowing */);
74	      // We are fine with a null FilterConfig here since we ensure that MockBuilder never invokes
75	      // its parent here
76	      RateLimitManager.Builder builder =
77	          new MockBuilder(
78	              null /* dummy SolrZkClient */, new MockRequestRateLimiter(rateLimiterConfig));
79	      RateLimitManager rateLimitManager = builder.build();
80	
81	      solrDispatchFilter.replaceRateLimitManager(rateLimitManager);
